const first = $input.first()?.json || {};
const job = first.body || first;
const tenant = job.tenant || {};
const payload = job.payload || job;
const normalize = (value) => String(value || '').trim();
const defaultCountryCode = normalize($vars.QC_DEFAULT_PHONE_COUNTRY_CODE || '+1');
const toE164 = (value) => {
  const raw = normalize(value);
  if (!raw) return '';
  if (raw.startsWith('+')) return '+' + raw.slice(1).replace(/\D/g, '');
  if (raw.startsWith('00')) return '+' + raw.slice(2).replace(/\D/g, '');
  const digits = raw.replace(/\D/g, '');
  if (!digits) return '';
  const code = defaultCountryCode.startsWith('+') ? defaultCountryCode : '+' + defaultCountryCode;
  return digits.startsWith('0') ? code + digits.slice(1) : '+' + digits;
};
const customerPhone = normalize(payload.customerPhone);
const ownerPhone = normalize(payload.ownerPhone);
return [{ json: {
  jobType: job.jobType || 'appointment.status_updated',
  jobId: job.jobId || payload.idempotencyKey || 'appointment_' + Date.now(),
  action: normalize(payload.action || 'status_updated'),
  status: normalize(payload.status || 'Pending'),
  previousStatus: normalize(payload.previousStatus),
  tenantId: String(tenant.id || ''),
  tenantEmail: normalize(tenant.email || job.tenantEmail),
  ownerPhone,
  ownerPhoneE164: toE164(ownerPhone),
  customerName: normalize(payload.customerName || 'Customer'),
  customerPhone,
  customerPhoneE164: toE164(customerPhone),
  customerEmail: normalize(payload.customerEmail),
  appointmentDate: normalize(payload.appointmentDate),
  appointmentTime: normalize(payload.appointmentTime),
  appointmentType: normalize(payload.appointmentType || 'Consultation'),
  appointmentId: normalize(payload.appointmentId),
  occurredAt: normalize(job.occurredAt || new Date().toISOString())
} }];
